"""A tiny Caesar cipher utility."""


def encrypt(text: str, shift: int) -> str:
    """Return *text* with each alphabetic character shifted by *shift* positions."""
    result = []
    shift %= 26

    for char in text:
        if "a" <= char <= "z":
            result.append(chr((ord(char) - ord("a") + shift) % 26 + ord("a")))
        elif "A" <= char <= "Z":
            result.append(chr((ord(char) - ord("A") + shift) % 26 + ord("A")))
        else:
            result.append(char)

    return "".join(result)
